import{_ as a,C as s,o as i,c as o,a3 as t,E as n}from"./chunks/framework.bGC-1KKp.js";const x=JSON.parse('{"title":"Séance 2 — Le mandat, les contraintes et les risques","description":"","frontmatter":{"title":"Séance 2 — Le mandat, les contraintes et les risques","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/02-contraintes-et-risques.md","filePath":"modules/01-faisabilite/02-contraintes-et-risques.md"}'),d={name:"modules/01-faisabilite/02-contraintes-et-risques.md"};function u(c,e,g,p,h,m){const r=s("TriExigences"),l=s("PhrasesCachees");return i(),o("div",null,[e[0]||(e[0]=t('<h1 id="seance-2-—-le-mandat-les-contraintes-et-les-risques" tabindex="-1">Séance 2 — Le mandat, les contraintes et les risques <a class="header-anchor" href="#seance-2-—-le-mandat-les-contraintes-et-les-risques" aria-label="Permalink to &quot;Séance 2 — Le mandat, les contraintes et les risques&quot;">​</a></h1><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li>Relever les contraintes d&#39;un mandat réel et les classer.</li><li>Préciser les contraintes de budget, de délai, de personnel et de technologie.</li><li>Distinguer ce que le site doit <strong>faire</strong> de la façon dont il doit le <strong>faire</strong> : vitesse, sécurité, accessibilité, Loi 25, navigateurs.</li><li>Distinguer une <strong>contrainte</strong> d&#39;un <strong>risque</strong>, et évaluer un risque selon ses chances d&#39;arriver et ses conséquences.</li><li>Dresser la liste des problèmes techniques à prévoir.</li></ul><h2 id="deroulement-de-la-seance" tabindex="-1">Déroulement de la séance <a class="header-anchor" href="#deroulement-de-la-seance" aria-label="Permalink to &quot;Déroulement de la séance&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Heure</th><th style="text-align:left;">Activité</th></tr></thead><tbody><tr><td style="text-align:left;">18 h 30</td><td style="text-align:left;">Retour sur le Lab 01 : le tableau des quatre paires</td></tr><tr><td style="text-align:left;">18 h 45</td><td style="text-align:left;">Formation des équipes</td></tr><tr><td style="text-align:left;">18 h 55</td><td style="text-align:left;"><a href="./../../mandat/">Le mandat du client</a> : lecture en équipe</td></tr><tr><td style="text-align:left;">19 h 15</td><td style="text-align:left;">Les contraintes de ressources, en détail</td></tr><tr><td style="text-align:left;">19 h 30</td><td style="text-align:left;">Ce que le site doit faire, et comment il doit le faire</td></tr><tr><td style="text-align:left;">19 h 50</td><td style="text-align:left;">Activité — Les cinq phrases du client</td></tr><tr><td style="text-align:left;">20 h 10</td><td style="text-align:left;">Pause</td></tr><tr><td style="text-align:left;">20 h 25</td><td style="text-align:left;">Contrainte ou risque ? La matrice des risques</td></tr><tr><td style="text-align:left;">20 h 40</td><td style="text-align:left;"><a href="./../../labs/lab02-radiographie-mandat">Lab 02 — Radiographie du mandat</a> (en équipe)</td></tr><tr><td style="text-align:left;">21 h 35</td><td style="text-align:left;">Correction commentée en grand groupe</td></tr><tr><td style="text-align:left;">21 h 55</td><td style="text-align:left;">L&#39;évaluation 1 : ce qui s&#39;en vient</td></tr></tbody></table><hr><h2 id="retour-sur-le-lab-01" tabindex="-1">Retour sur le Lab 01 <a class="header-anchor" href="#retour-sur-le-lab-01" aria-label="Permalink to &quot;Retour sur le Lab 01&quot;">​</a></h2><p>Chaque duo donne ses résultats : plateforme, score de performance mobile, verdict. On remplit ensemble le tableau.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Paire</th><th style="text-align:left;">Site</th><th style="text-align:left;">Plateforme</th><th style="text-align:center;">Performance mobile</th><th style="text-align:center;">Plus facile à faire évoluer ?</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;">La Banquise</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">1</td><td style="text-align:left;">Casse-Croûte Courteau</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;">Thaï Express</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;">Ashton</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;">Schwartz&#39;s</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;">Commensal</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;">Joe Beef</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;">Épi, buvette de quartier</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><p><strong>La question à retenir :</strong> un site peut être beau, rapide et difficile à faire évoluer. C&#39;est ce genre de nuance qu&#39;on attend dans un rapport de faisabilité.</p><hr><h2 id="formation-des-equipes" tabindex="-1">Formation des équipes <a class="header-anchor" href="#formation-des-equipes" aria-label="Permalink to &quot;Formation des équipes&quot;">​</a></h2><ul><li>Équipes de <strong>2 ou 3 personnes</strong>, qui restent <strong>les mêmes toute la session</strong> (évaluations 1, 2 et 3).</li><li>Votre équipe est une petite agence Web : <strong>Studio Web FC</strong>. Donnez-lui un nom d&#39;équipe si vous voulez.</li><li>Créez tout de suite un <strong>dossier partagé</strong> (OneDrive ou Teams) où vous rangerez tous les documents du mandat.</li></ul><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Avant de partir ce soir</strong><br> Écrivez-vous une <strong>entente d&#39;équipe</strong> de cinq lignes : comment vous communiquez, à quel moment vous travaillez ensemble, qui remet les travaux, et ce que vous faites si quelqu&#39;un ne livre pas sa part. </div><hr><h2 id="le-mandat-du-client" tabindex="-1">Le mandat du client <a class="header-anchor" href="#le-mandat-du-client" aria-label="Permalink to &quot;Le mandat du client&quot;">​</a></h2><p>Le mandat qui servira toute la session : <strong><a href="./../../mandat/">Aventure Saint-Maurice</a></strong>, un centre de plein air qui veut refaire son site Web.</p><p>Lisez-le en équipe : le courriel du client, les notes de la première rencontre et les chiffres. Pendant la lecture, <strong>surlignez</strong> avec trois couleurs :</p><table tabindex="0"><thead><tr><th style="text-align:left;">Couleur</th><th style="text-align:left;">Ce que vous surlignez</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Jaune</strong></td><td style="text-align:left;">Ce que le client <strong>veut</strong> que le site fasse</td></tr><tr><td style="text-align:left;"><strong>Rose</strong></td><td style="text-align:left;">Ce qui <strong>limite</strong> les choix : argent, temps, personnes, technologie, lois</td></tr><tr><td style="text-align:left;"><strong>Vert</strong></td><td style="text-align:left;">Ce qui est <strong>flou</strong> ou qu&#39;il faudra <strong>vérifier</strong></td></tr></tbody></table><hr><h2 id="les-contraintes-de-ressources-en-detail" tabindex="-1">Les contraintes de ressources, en détail <a class="header-anchor" href="#les-contraintes-de-ressources-en-detail" aria-label="Permalink to &quot;Les contraintes de ressources, en détail&quot;">​</a></h2><p>À la séance 1, on a vu trois sortes de contraintes : techniques, organisationnelles et de ressources. Dans un rapport de faisabilité, on regarde de plus près quatre éléments.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Élément</th><th style="text-align:left;">La question à se poser</th><th style="text-align:left;">Dans le mandat</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Budget</strong></td><td style="text-align:left;">Combien pour construire ? Et combien <strong>chaque année</strong> ensuite ?</td><td style="text-align:left;">8 000 $ pour construire, peut-être 13 000 $. Aucun montant prévu pour les coûts annuels.</td></tr><tr><td style="text-align:left;"><strong>Délai</strong></td><td style="text-align:left;">La date est-elle <strong>ferme</strong> ou <strong>souhaitée</strong> ? De quoi dépend-elle ?</td><td style="text-align:left;">Le 1<sup>er</sup> mars est ferme. Les cartes-cadeaux « pour Noël » sont souhaitées.</td></tr><tr><td style="text-align:left;"><strong>Personnel</strong></td><td style="text-align:left;">Qui fera le travail, <strong>avant</strong> et <strong>après</strong> le lancement ? Avec quelles compétences ? Quand est-il disponible ?</td><td style="text-align:left;">Mélanie seule l&#39;hiver, débordée l&#39;été. Des guides différents chaque année.</td></tr><tr><td style="text-align:left;"><strong>Technologie</strong></td><td style="text-align:left;">Qu&#39;est-ce qui <strong>existe déjà</strong> et qu&#39;il faut garder, remplacer ou relier ?</td><td style="text-align:left;">Wix, Square, Viator, Google Workspace, le nom de domaine, l&#39;Excel.</td></tr></tbody></table><div class="bg-red-50 border border-red-300 text-red-900 rounded-lg p-4 mb-5"><strong>Pièges fréquents</strong><br><ul class="list-disc pl-5"><li><strong>Prendre le budget annoncé pour le budget réel.</strong> Le client a donné un chiffre pour la construction. Il n&#39;a pas pensé aux abonnements, aux frais par transaction ni à l&#39;entretien.</li><li><strong>Oublier que le délai dépend du client.</strong> Si les photos et les textes arrivent en février, le site ne sera pas prêt le 1<sup>er</sup> mars, peu importe la vitesse de l&#39;équipe.</li><li><strong>Compter seulement ceux qui construisent.</strong> Il faut aussi savoir qui fera vivre le site pendant cinq ans.</li><li><strong>Oublier ce qui existe déjà.</strong> Le nom de domaine et les adresses courriel fonctionnent aujourd&#39;hui. Le projet ne doit pas les briser.</li></ul></div><hr><h2 id="ce-que-le-site-doit-faire-et-comment-il-doit-le-faire" tabindex="-1">Ce que le site doit faire, et comment il doit le faire <a class="header-anchor" href="#ce-que-le-site-doit-faire-et-comment-il-doit-le-faire" aria-label="Permalink to &quot;Ce que le site doit faire, et comment il doit le faire&quot;">​</a></h2><p>Un client décrit surtout ce que le site doit <strong>faire</strong> : réserver, payer, signer une décharge. On appelle ça les <strong>exigences fonctionnelles</strong>.</p><p>Mais il y a aussi la <strong>façon</strong> dont il doit le faire : assez vite, de façon sécuritaire, pour tout le monde, dans le respect de la loi. On appelle ça les <strong>exigences non fonctionnelles</strong>. Le client en parle rarement, mais c&#39;est souvent là que se cachent les problèmes techniques.</p><h3 id="a-vous-de-classer" tabindex="-1">À vous de classer <a class="header-anchor" href="#a-vous-de-classer" aria-label="Permalink to &quot;À vous de classer&quot;">​</a></h3>',29)),n(r),e[1]||(e[1]=t('<h3 id="les-cinq-exigences-non-fonctionnelles-a-verifier-dans-tout-projet" tabindex="-1">Les cinq exigences non fonctionnelles à vérifier dans tout projet <a class="header-anchor" href="#les-cinq-exigences-non-fonctionnelles-a-verifier-dans-tout-projet" aria-label="Permalink to &quot;Les cinq exigences non fonctionnelles à vérifier dans tout projet&quot;">​</a></h3><h4 id="_1-la-vitesse" tabindex="-1">1. La vitesse <a class="header-anchor" href="#_1-la-vitesse" aria-label="Permalink to &quot;1. La vitesse&quot;">​</a></h4><ul><li>Plus de la moitié des visites se font sur téléphone, souvent avec un réseau moyen.</li><li>Les repères de Google (Core Web Vitals) : l&#39;élément principal de la page devrait s&#39;afficher en <strong>moins de 2,5 secondes</strong> (le LCP, vu au Lab 01).</li><li>Ce qui ralentit le plus : les images et les vidéos trop lourdes, les scripts de services externes (publicité, clavardage, suivi).</li></ul><h4 id="_2-la-securite" tabindex="-1">2. La sécurité <a class="header-anchor" href="#_2-la-securite" aria-label="Permalink to &quot;2. La sécurité&quot;">​</a></h4><ul><li>Le cadenas (HTTPS) est un minimum, pas une garantie.</li><li><strong>Ne jamais garder les numéros de carte de crédit</strong> sur le site. On confie le paiement à un service spécialisé (Square, Stripe, PayPal…) qui respecte les normes de l&#39;industrie.</li><li>Qui a accès à quoi ? Un guide n&#39;a pas besoin de voir les revenus. L&#39;employée d&#39;accueil n&#39;a pas besoin de pouvoir supprimer le site.</li><li>Les mises à jour, les sauvegardes et les mots de passe : qui s&#39;en occupe, et à quelle fréquence ?</li></ul><h4 id="_3-l-accessibilite" tabindex="-1">3. L&#39;accessibilité <a class="header-anchor" href="#_3-l-accessibilite" aria-label="Permalink to &quot;3. L&#39;accessibilité&quot;">​</a></h4><ul><li>Un site accessible peut être utilisé par une personne aveugle, malvoyante, sourde, qui ne peut pas se servir d&#39;une souris, ou qui a une incapacité cognitive.</li><li>La référence internationale : les <strong>WCAG</strong> (Web Content Accessibility Guidelines), niveau <strong>AA</strong>.</li><li>Au Québec, les organismes publics doivent respecter un standard gouvernemental. Pour une entreprise privée, c&#39;est une bonne pratique… et parfois une <strong>condition d&#39;une subvention</strong>, comme dans notre mandat.</li><li>Exemples concrets : texte de remplacement des images, contraste suffisant, navigation au clavier, sous-titres des vidéos, formulaires bien identifiés.</li></ul><h4 id="_4-la-loi-25-et-les-renseignements-personnels" tabindex="-1">4. La Loi 25 et les renseignements personnels <a class="header-anchor" href="#_4-la-loi-25-et-les-renseignements-personnels" aria-label="Permalink to &quot;4. La Loi 25 et les renseignements personnels&quot;">​</a></h4><p>La <strong>Loi 25</strong> modernise les règles québécoises de protection des renseignements personnels. Elle s&#39;applique à toute entreprise qui recueille des renseignements sur des Québécois, <strong>petite ou grande</strong>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ce que la loi demande</th><th style="text-align:left;">Ce que ça veut dire pour un site Web</th></tr></thead><tbody><tr><td style="text-align:left;">Une <strong>personne responsable</strong> de la protection des renseignements personnels</td><td style="text-align:left;">Par défaut, c&#39;est la personne la plus haut placée de l&#39;entreprise : ici, Mélanie. Son titre et ses coordonnées doivent être publiés sur le site.</td></tr><tr><td style="text-align:left;">Une <strong>politique de confidentialité</strong> en termes simples et clairs</td><td style="text-align:left;">Une page qui explique ce qu&#39;on recueille, pourquoi, combien de temps on le garde et qui y a accès.</td></tr><tr><td style="text-align:left;">Un <strong>consentement</strong> clair</td><td style="text-align:left;">Les témoins (cookies) de suivi et de publicité doivent être <strong>désactivés par défaut</strong>. La bannière doit permettre de refuser aussi facilement que d&#39;accepter.</td></tr><tr><td style="text-align:left;">Un consentement <strong>exprès</strong> pour les renseignements <strong>sensibles</strong></td><td style="text-align:left;">Les renseignements de santé de la décharge sont sensibles : le client doit les fournir en sachant clairement pourquoi.</td></tr><tr><td style="text-align:left;">Une <strong>évaluation</strong> avant d&#39;envoyer des renseignements <strong>hors du Québec</strong></td><td style="text-align:left;">Si le système de réservation garde ses données aux États-Unis, il faut évaluer les risques avant de l&#39;adopter.</td></tr><tr><td style="text-align:left;">Déclarer les <strong>incidents</strong> de confidentialité</td><td style="text-align:left;">Une fuite qui présente un risque sérieux doit être déclarée à la Commission d&#39;accès à l&#39;information et aux personnes touchées.</td></tr><tr><td style="text-align:left;">Détruire ou anonymiser les renseignements quand on n&#39;en a plus besoin</td><td style="text-align:left;">Les boîtes de décharges « depuis 2014 » posent déjà problème.</td></tr></tbody></table><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Ce n&#39;est pas un avis juridique</strong><br> Dans un rapport de faisabilité, on <strong>signale</strong> les enjeux de la Loi 25 et on recommande au client de valider avec un conseiller juridique. On ne s&#39;improvise pas avocat. Pour en savoir plus : le site de la <a href="https://www.cai.gouv.qc.ca/" target="_blank">Commission d&#39;accès à l&#39;information du Québec</a>. </div><p>La <strong>Charte de la langue française</strong> s&#39;ajoute : un site offert au Québec doit être disponible en français, et la version française doit être au moins aussi complète que les autres versions.</p><h4 id="_5-les-navigateurs-et-les-appareils-a-supporter" tabindex="-1">5. Les navigateurs et les appareils à supporter <a class="header-anchor" href="#_5-les-navigateurs-et-les-appareils-a-supporter" aria-label="Permalink to &quot;5. Les navigateurs et les appareils à supporter&quot;">​</a></h4><ul><li>On ne peut pas tester sur tous les appareils : il faut <strong>choisir</strong> une liste et l&#39;écrire dans le rapport.</li><li>Une liste raisonnable en 2026 : les deux dernières versions de <strong>Chrome, Safari, Edge et Firefox</strong>, sur ordinateur, et <strong>Safari sur iPhone</strong> et <strong>Chrome sur Android</strong>, sur téléphone.</li><li>Pour choisir, on regarde les statistiques du site actuel. Ici, il n&#39;y en a pas : c&#39;est une information à obtenir.</li><li>Attention à <strong>Safari sur iPhone</strong> : au Québec, il représente une grande part des visites sur téléphone, et c&#39;est souvent là que des problèmes apparaissent.</li></ul><hr><h2 id="activite-—-les-cinq-phrases-du-client" tabindex="-1">Activité — Les cinq phrases du client <a class="header-anchor" href="#activite-—-les-cinq-phrases-du-client" aria-label="Permalink to &quot;Activité — Les cinq phrases du client&quot;">​</a></h2><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (20 min, en équipe)</strong><br> Chacune des phrases ci-dessous a été prononcée pendant la rencontre. Elles ont l&#39;air banales, mais chacune cache un problème technique. <ol class="list-decimal pl-5"><li>Pour chaque phrase, trouvez le problème caché et notez une question à poser au client.</li><li>Estimez ce que ça pourrait coûter : <strong>$</strong>, <strong>$$</strong> ou <strong>$$$</strong>. Est-ce un coût unique ou annuel ?</li><li>Ne cliquez sur « Révéler » qu&#39;une fois votre réponse écrite. On compare en grand groupe.</li></ol></div>',17)),n(l),e[2]||(e[2]=t('<p><strong>Ce qu&#39;il faut retenir :</strong> le client ne ment pas et il n&#39;est pas naïf. Il ne sait simplement pas ce que sa demande implique. C&#39;est le rôle de l&#39;analyste de le lui expliquer <strong>avant</strong> que le projet commence, pas après.</p><hr><h2 id="contrainte-ou-risque" tabindex="-1">Contrainte ou risque ? <a class="header-anchor" href="#contrainte-ou-risque" aria-label="Permalink to &quot;Contrainte ou risque ?&quot;">​</a></h2><p>Les deux mots se ressemblent, mais ils ne veulent pas dire la même chose.</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">Contrainte</th><th style="text-align:left;">Risque</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Définition</strong></td><td style="text-align:left;">Une limite <strong>certaine</strong>, connue dès le départ</td><td style="text-align:left;">Un événement <strong>incertain</strong> qui pourrait nuire au projet</td></tr><tr><td style="text-align:left;"><strong>Question</strong></td><td style="text-align:left;">Qu&#39;est-ce qui limite nos choix ?</td><td style="text-align:left;">Qu&#39;est-ce qui pourrait mal tourner ?</td></tr><tr><td style="text-align:left;"><strong>Exemple</strong></td><td style="text-align:left;">Le site doit être en ligne le 1<sup>er</sup> mars.</td><td style="text-align:left;">Les photos arrivent en retard et le site n&#39;est pas prêt le 1<sup>er</sup> mars.</td></tr><tr><td style="text-align:left;"><strong>Ce qu&#39;on en fait</strong></td><td style="text-align:left;">On en tient compte dans les choix</td><td style="text-align:left;">On l&#39;évalue, puis on prévoit une mesure pour le réduire</td></tr></tbody></table><h3 id="d-ou-viennent-les-risques" tabindex="-1">D&#39;où viennent les risques ? <a class="header-anchor" href="#d-ou-viennent-les-risques" aria-label="Permalink to &quot;D&#39;où viennent les risques ?&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Origine</th><th style="text-align:left;">Exemples</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Techniques</strong></td><td style="text-align:left;">Deux systèmes qui ne se parlent pas comme prévu; des données perdues pendant le transfert; un outil qui ferme ses portes; un site trop lent.</td></tr><tr><td style="text-align:left;"><strong>Organisationnels</strong></td><td style="text-align:left;">Le client livre ses contenus en retard; personne ne met le site à jour; les décideurs changent d&#39;avis; un accès essentiel est au nom de quelqu&#39;un d&#39;autre.</td></tr></tbody></table><h3 id="evaluer-un-risque" tabindex="-1">Évaluer un risque <a class="header-anchor" href="#evaluer-un-risque" aria-label="Permalink to &quot;Évaluer un risque&quot;">​</a></h3><p>On évalue chaque risque selon deux questions :</p><ol><li><strong>Quelles sont les chances que ça arrive ?</strong> Faible, moyenne ou élevée.</li><li><strong>Si ça arrive, quelles sont les conséquences ?</strong> Faibles, moyennes ou graves.</li></ol><p>On place ensuite le risque dans une <strong>matrice</strong>. Plus il est en haut à droite, plus il faut s&#39;en occuper.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Chances ↓ · Conséquences →</th><th style="text-align:center;">Faibles</th><th style="text-align:center;">Moyennes</th><th style="text-align:center;">Graves</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Élevées</strong></td><td style="text-align:center;">🟨 À surveiller</td><td style="text-align:center;">🟥 À traiter</td><td style="text-align:center;">🟥 À traiter en priorité</td></tr><tr><td style="text-align:left;"><strong>Moyennes</strong></td><td style="text-align:center;">🟩 À accepter</td><td style="text-align:center;">🟨 À surveiller</td><td style="text-align:center;">🟥 À traiter</td></tr><tr><td style="text-align:left;"><strong>Faibles</strong></td><td style="text-align:center;">🟩 À accepter</td><td style="text-align:center;">🟩 À accepter</td><td style="text-align:center;">🟨 Prévoir un plan B</td></tr></tbody></table><p>Pour chaque risque placé dans la zone rouge, on propose une <strong>mesure</strong> : ce qu&#39;on fera pour qu&#39;il arrive moins souvent, ou pour que ses conséquences soient moins graves.</p><blockquote><p><em>Exemple :</em> « Les photos arrivent en retard. » → <strong>Mesure :</strong> fixer au 15 janvier la date limite de remise des contenus et prévoir des photos temporaires.</p></blockquote><hr><h2 id="la-liste-des-problemes-techniques-a-prevoir" tabindex="-1">La liste des problèmes techniques à prévoir <a class="header-anchor" href="#la-liste-des-problemes-techniques-a-prevoir" aria-label="Permalink to &quot;La liste des problèmes techniques à prévoir&quot;">​</a></h2><p>C&#39;est la synthèse de tout le travail de ce soir. Pour chaque problème, on écrit :</p><table tabindex="0"><thead><tr><th style="text-align:left;">Problème</th><th style="text-align:left;">Pourquoi c&#39;est un problème</th><th style="text-align:left;">Ce qu&#39;il faut vérifier ou demander</th></tr></thead><tbody><tr><td style="text-align:left;"><em>Ex. :</em> Les réservations Viator doivent partager les places avec le nouveau site.</td><td style="text-align:left;">Sinon, les doubles réservations continuent.</td><td style="text-align:left;">Quels outils de réservation sont connectés à Viator ? Combien coûtent-ils ?</td></tr></tbody></table><p>Cette liste servira directement à l&#39;<strong>évaluation 1</strong>, puis à la rencontre avec le client à la <strong>séance 9</strong>.</p><hr><h2 id="l-evaluation-1-ce-qui-s-en-vient" tabindex="-1">L&#39;évaluation 1 : ce qui s&#39;en vient <a class="header-anchor" href="#l-evaluation-1-ce-qui-s-en-vient" aria-label="Permalink to &quot;L&#39;évaluation 1 : ce qui s&#39;en vient&quot;">​</a></h2><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Rapport de faisabilité technique — Évaluation technique (20 %)</strong><br><ul class="list-disc pl-5"><li>En équipe, sur le mandat Aventure Saint-Maurice.</li><li>Remise à la <strong>séance 7 (11 novembre)</strong> sur LÉA. Le français compte pour 10 %.</li><li>Le rapport <strong>décrit la situation</strong> : ce que le projet exige, ce qui le contraint, les risques et les technologies qui existent pour le réaliser. Il ne recommande <strong>encore rien</strong> : les choix viendront à l&#39;évaluation 2.</li><li>Le travail de ce soir (contraintes, exigences, risques, problèmes à prévoir) en est le point de départ.</li></ul></div><hr><h2 id="a-faire-maintenant" tabindex="-1">À faire maintenant <a class="header-anchor" href="#a-faire-maintenant" aria-label="Permalink to &quot;À faire maintenant&quot;">​</a></h2><p><a href="./../../labs/lab02-radiographie-mandat">Lab 02 — Radiographie du mandat</a></p>',25))])}const q=a(d,[["render",u]]);export{x as __pageData,q as default};
